steps.script:
var c = tree.root.get_node("Main").shooting_controller
var rows = []
var it = c.weapon_tree.get_root().get_first_child()
while it:
	rows.append(str(it.get_text(1)))
	it = it.get_next()
if rows.size() != 1:
	return str(rows)
for r in rows:
	if not r.contains("Blade Champion Beta"):
		return str(rows)
return "ok"

var p = PhaseManager.get_current_phase_instance()
if p.pending_assignments.size() != 2:
	return "pending %d" % p.pending_assignments.size()
for a in p.pending_assignments:
	if str(a.get("target_unit_id", "")) != "U_PROSECUTORS_A":
		return str(a)
return "ok"

var c = tree.root.get_node("Main").shooting_controller
var rows = []
var it = c.weapon_tree.get_root().get_first_child()
while it:
	rows.append(str(it.get_text(1)))
	it = it.get_next()
if rows.size() != 2:
	return str(rows)
for r in rows:
	if not r.contains("Prosecutors"):
		return str(rows)
return "ok"

var c = tree.root.get_node("Main").shooting_controller
var it = c.weapon_tree.get_root().get_first_child()
while it:
	if str(it.get_metadata(0)) == "big_shoota_ranged":
		var st = str(it.get_first_child().get_text(0))
		return "ok" if st.contains("RF3") else st
	it = it.get_next()
return "no big shoota row"

var p = PhaseManager.get_current_phase_instance()
for d in p.dice_log:
	if typeof(d) == TYPE_DICTIONARY and str(d.get("context", "")) == "to_hit" and str(d.get("target_unit_id", "")) == "U_PROSECUTORS_A" and int(d.get("rapid_fire_value", 0)) == 3:
		return true
return false
